import type { Container } from "postcss";
import type { PostcssResult } from "stylelint";
/**
 * Asks whether `block-closing-brace-empty-line-before` leaves an empty line in the run in front of a block's closing brace.
 *
 * The rule always judges, and only its expectation moves: `except` turns the option over, `after-closing-brace` for a block holding no declaration and `last-nested` for the block a chain of nested blocks ends in, and otherwise `always-multi-line` wants the line in a multi-line block alone. The reversal asks for the line unconditionally, which it may not do where the run is the one `block-opening-brace-newline-after` writes: no file satisfies both, so the rule asks for nothing and the neighbor is free to write. The neighbor is asked with its turn not yet come and with it come, so the answer is one file either way.
 *
 * The rule and the gate below read this one answer, which is what keeps a promise made to the neighbor and a decision made by the rule from drifting apart.
 * @param node - The block's statement.
 * @param result - The Stylelint result, which holds the configuration.
 * @param option - The empty line rule's primary option.
 * @param secondary - Its secondary options.
 * @param isSingleLine - Whether the block is one line as the asking side leaves it.
 * @returns True where the empty line stands.
 */
export declare function keepsAnEmptyLineBeforeBrace(node: Container, result: PostcssResult, option: string, secondary: Record<string, unknown>, isSingleLine: boolean): boolean;
/**
 * Asks whether a rule asking for no whitespace in front of a closing brace is held off the run by one asking for a break there: the break stands in front of the brace whether the block stays multi-line or collapses into one line, and a run of no whitespace is not a break, so the two spellings they accept never meet.
 *
 * This is {@link writesBlockAfter}'s own first question, and it is asked of the asking rule beside it: a block holding nothing but comments has the run in front of its closing brace standing where the run after its opening brace would be, and where a neighbor holds the row, this rule judges the run behind the opening brace instead and leaves the row to the neighbor. Both answers are the gate's, so they cannot drift apart. The two readings are not the same verdict, and the rule needs only this one: held means the row before the closing brace is not this rule's to write, not that the block has no file at all.
 * @param node - The block's statement, a node of the root the rules read.
 * @param result - The Stylelint result, which holds the configuration.
 * @param primary - The asking rule's primary option.
 * @param isSingleLine - Whether the block is one line as it stands or as the asking rule's write leaves it.
 * @param standing - The run in front of the closing brace as it stands.
 * @returns True where a break holds the run.
 */
export declare function heldByABreakBeforeTheBrace(node: Container, result: PostcssResult, primary: string, isSingleLine: boolean, standing: string): boolean;
/**
 * Asks whether a space rule requires a run the opening-brace rule cannot write in front of this block's closing brace.
 * @param node - The block's statement.
 * @param result - The PostCSS result, which holds the configuration.
 * @param primary - The asking rule's primary option.
 * @param isSingleLine - Whether the block is one line as the write leaves it.
 * @param standing - The run in front of the closing brace as it stands.
 * @returns True where the space rule and the asking rule accept no common run.
 */
export declare function closingBraceSpacePreventsWritingBlockAfter(node: Container, result: PostcssResult, primary: string, isSingleLine: boolean, standing: string): boolean;
/**
 * Asks whether `block-opening-brace-newline-after` is the one to write the run in front of the closing brace of a block holding nothing but comments, the run the three `block-closing-brace-*-before` rules write.
 *
 * It writes only where every one of the three that speaks of the block as the write leaves it accepts a spelling it accepts too; otherwise the run would be taken straight back out, and the two rules would take it in turns for as long as `--fix` ran. Sharing a spelling rather than accepting the written one is what lets `block-closing-brace-empty-line-before` double the break this rule writes.
 *
 * A run holding a stray semicolon no neighbor takes out is two runs: the asking rule writes the whitespace in front of the first such semicolon, and the three write the whitespace in front of the brace. Only a neighbor that may take back what the asking rule writes there is asked then: `block-closing-brace-newline-before` under `never-multi-line`, which takes every break of the run out, and, where no break stands behind the first semicolon, its other options and `block-closing-brace-empty-line-before`, which may then put their break in front of it. Where a break stands behind it, they accept either spelling the asking rule writes in front. `block-closing-brace-space-before` writes behind the last semicolon alone.
 *
 * Run order is not asked: one rule asks and the three write whatever the configuration lists, so no order changes the answer. The copy of each of the three reading the root is asked.
 * @param node - The block's statement, a node of the root the rules read.
 * @param result - The Stylelint result, which holds the configuration.
 * @param primary - The asking rule's primary option.
 * @param isSingleLine - Whether the block is one line as the write leaves it.
 * @param standing - The run in front of the closing brace as it stands.
 * @returns True where the asking rule writes the run.
 */
export declare function writesBlockAfter(node: Container, result: PostcssResult, primary: string, isSingleLine: boolean, standing: string): boolean;
